challenge.solution:
def set_level(level):
    if level < 1 or level > 10:
        raise ValueError("Seviye 1 ile 10 arasında olmalı")
    return level

print(set_level(3))

check.python:
assert set_level(1) == 1 and set_level(10) == 10, "1 ve 10 geçerli seviyeler."
for bad in (0, 11, -3):
    try:
        set_level(bad)
    except ValueError:
        pass
    else:
        raise AssertionError("set_level(" + str(bad) + ") ValueError fırlatmalı.")

