messages = ["12 / 4", "5 / 0", "on / 2"]


def calc(message):
    parts = message.split("/")
    try:
        result = float(parts[0]) / float(parts[1])
    except ValueError:
        return "Sayıları anlayamadım."
    except ZeroDivisionError:
        return "Sıfıra bölemem!"
    return f"Sonuç: {result}"


for message in messages:
    print(calc(message))

def parse_grade(text):
    grade = int(text)
    if grade < 0 or grade > 100:
        raise ValueError("not 0 ile 100 arasında olmalı")
    return grade


entries = ["85", "yüz", "70", "120", ""]
grades = []
for entry in entries:
    try:
        grades.append(parse_grade(entry))
    except ValueError:
        print(f"'{entry}' geçersiz")
print("Geçerli notlar:", grades)

check.python:
assert parse_grade("55") == 55, "parse_grade(\"55\") 55 döndürmeli."
assert parse_grade("0") == 0 and parse_grade("100") == 100, "0 ve 100 geçerli notlar."
for bad in ["abc", "101", "-5"]:
    try:
        parse_grade(bad)
    except ValueError:
        pass
    else:
        raise AssertionError("parse_grade('" + bad + "') ValueError fırlatmalı.")
